package org.padtv.bridge;
import android.util.AttributeSet;
import org.w3c.dom.*;
public final class XmlAttributes implements AttributeSet {
    private final Element element;private final android.content.res.Resources resources;public XmlAttributes(Element e,android.content.res.Resources r){element=e;resources=r;}
    public int getAttributeCount(){return element.getAttributes().getLength();}public String getAttributeName(int i){return element.getAttributes().item(i).getNodeName();}public String getAttributeValue(int i){return element.getAttributes().item(i).getNodeValue();}public String getAttributeValue(String ns,String n){return element.hasAttribute(n)?element.getAttribute(n):null;}public String getPositionDescription(){return element.getTagName();}
    public int getAttributeNameResource(int i){throw new UnsupportedOperationException("Framework attribute IDs require the Android framework resource table");}
    private int number(String v,int d){if(v==null)return d;if(v.startsWith("@"))return resources.getIdentifier(v,null,null);return Integer.decode(v);}private int choice(String v,String[] options,int d){for(int i=0;i<options.length;i++)if(options[i].equals(v))return i;return d;}
    public int getAttributeListValue(String n,String a,String[] o,int d){return choice(getAttributeValue(n,a),o,d);}public boolean getAttributeBooleanValue(String n,String a,boolean d){String v=getAttributeValue(n,a);return v==null?d:Boolean.parseBoolean(v);}public int getAttributeResourceValue(String n,String a,int d){return number(getAttributeValue(n,a),d);}public int getAttributeIntValue(String n,String a,int d){return number(getAttributeValue(n,a),d);}public int getAttributeUnsignedIntValue(String n,String a,int d){return getAttributeIntValue(n,a,d);}public float getAttributeFloatValue(String n,String a,float d){String v=getAttributeValue(n,a);return v==null?d:Float.parseFloat(v);}
    public int getAttributeListValue(int i,String[] o,int d){return choice(getAttributeValue(i),o,d);}public boolean getAttributeBooleanValue(int i,boolean d){String v=getAttributeValue(i);return v==null?d:Boolean.parseBoolean(v);}public int getAttributeResourceValue(int i,int d){return number(getAttributeValue(i),d);}public int getAttributeIntValue(int i,int d){return number(getAttributeValue(i),d);}public int getAttributeUnsignedIntValue(int i,int d){return getAttributeIntValue(i,d);}public float getAttributeFloatValue(int i,float d){String v=getAttributeValue(i);return v==null?d:Float.parseFloat(v);}
    public String getIdAttribute(){return getAttributeValue(null,"id");}public String getClassAttribute(){return getAttributeValue(null,"class");}public int getIdAttributeResourceValue(int d){return number(getIdAttribute(),d);}public int getStyleAttribute(){return number(getAttributeValue(null,"style"),0);}
}
